const assert = require("assert");
const { resolveSession } = require("./src/session.js");

(async () => {
  // 1. Same io + same sessionId: loadSession called only once
  {
    let calls = 0;
    const io = { loadSession: async () => { calls++; return { id: "s1", t: "A" }; } };
    const a = await resolveSession(io, "s1");
    const b = await resolveSession(io, "s1");
    assert.strictEqual(calls, 1, "expected single loadSession call");
    assert.strictEqual(a, b, "expected same cached session object");
    console.log("PASS memoization (single call, same object)");
  }

  // 2. Cross-tenant isolation: different io, same sessionId must not share cache
  {
    let callsA = 0, callsB = 0;
    const ioA = { loadSession: async () => { callsA++; return { id: "s1", t: "A" }; } };
    const ioB = { loadSession: async () => { callsB++; return { id: "s1", t: "B" }; } };
    const a1 = await resolveSession(ioA, "s1");
    const a2 = await resolveSession(ioA, "s1");
    const b1 = await resolveSession(ioB, "s1");
    const b2 = await resolveSession(ioB, "s1");
    assert.strictEqual(callsA, 1);
    assert.strictEqual(callsB, 1);
    assert.strictEqual(a1.t, "A");
    assert.strictEqual(b1.t, "B");
    assert.notStrictEqual(a1, b1, "tenants must never share session objects");
    console.log("PASS per-tenant isolation (no cross-tenant leak)");
  }

  // 3. Concurrent requests coalesce into a single load
  {
    let calls = 0;
    const io = { loadSession: () => new Promise(r => setTimeout(() => { calls++; r({ ok: true }); }, 20)) };
    const [x, y, z] = await Promise.all([resolveSession(io, "s"), resolveSession(io, "s"), resolveSession(io, "s")]);
    assert.strictEqual(calls, 1, "expected coalesced single load");
    assert.deepStrictEqual([x, y, z], [{ ok: true }, { ok: true }, { ok: true }]);
    console.log("PASS concurrency coalescing");
  }

  // 4. Failures propagate and are not cached (retry succeeds)
  {
    let calls = 0;
    const io = { loadSession: async () => { calls++; if (calls === 1) throw new Error("boom"); return { ok: true }; } };
    await assert.rejects(resolveSession(io, "s"), /boom/);
    const ok = await resolveSession(io, "s");
    assert.deepStrictEqual(ok, { ok: true });
    console.log("PASS errors propagate and are not cached");
  }

  console.log("\nAll checks passed.");
})().catch(e => { console.error("FAIL", e); process.exit(1); });
'

